    id: "kth-largest", title: "Kth Largest Element in an Array", level: "Medium", topic: "heaps", pattern: "Min-heap of size k",
    statement: "Return the kth largest element of `nums` (in sorted order, not the kth distinct). Try to beat sorting.",
    examples: [{ input: "nums = [3,2,1,5,6,4], k = 2", output: "5" }],
    fn: { js: "findKthLargest", py: "find_kth_largest" },
    starter: { js: "function findKthLargest(nums, k) {\n  \n}\n", py: "def find_kth_largest(nums, k):\n    pass\n" },
    solution: {
      js: "// Quickselect: average O(n)\nfunction findKthLargest(nums, k) {\n  const target = nums.length - k;\n  let lo = 0, hi = nums.length - 1;\n  while (true) {\n    const pivot = nums[hi];\n    let i = lo;\n    for (let j = lo; j < hi; j++) if (nums[j] < pivot) { [nums[i], nums[j]] = [nums[j], nums[i]]; i++; }\n    [nums[i], nums[hi]] = [nums[hi], nums[i]];\n    if (i === target) return nums[i];\n    if (i < target) lo = i + 1; else hi = i - 1;\n  }\n}\n",
      py: "import heapq\n\ndef find_kth_largest(nums, k):\n    heap = []                 # min-heap of the k largest seen\n    for x in nums:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    return heap[0]\n",
    },
