    statement: "Given coin denominations `coins` and an `amount`, return the fewest coins needed to make the amount, or -1 if impossible. You have unlimited coins of each kind.",
    examples: [{ input: "coins = [1,2,5], amount = 11", output: "3", explain: "5 + 5 + 1" }, { input: "coins = [2], amount = 3", output: "-1" }],
