      py: "def n_ck_mod(n, k):\n    MOD = 10**9 + 7\n    num = den = 1\n    for i in range(k):\n        num = num * (n - i) % MOD\n        den = den * (i + 1) % MOD\n    return num * pow(den, MOD - 2, MOD) % MOD\n",
